package ports

import (
	"context"

	"github.com/google/uuid"
	"github.com/luismarquitti/intellifinance-go/internal/domain"
)

// ReconciliationScanResult contains metrics and actions generated by a transfer reconciliation scan.
type ReconciliationScanResult struct {
	ScannedTransactionsCount int                     `json:"scanned_transactions_count"`
	ProposedActionsCount     int                     `json:"proposed_actions_count"`
	ProposedActions          []*domain.PendingAction `json:"proposed_actions"`
}

// TransferReconciliationService automatically discovers matching internal transfers and bill payments.
type TransferReconciliationService interface {
	ScanAndPropose(ctx context.Context, tenantID uuid.UUID) (*ReconciliationScanResult, error)
}
